const LETTERS=["A","B","C","D","E","F","G","H","I"];

let set=[],i=0,score=0,scored=0,states=[];
let quizStarted=false;

const $=id=>document.getElementById(id),
  subject=$("subject"),
  year=$("year"),
  order=$("order"),
  badges=$("badges"),
  prog=$("prog"),
  scoreEl=$("score"),
  bar=$("bar"),
  meta=$("meta"),
  question=$("question"),
  answers=$("answers"),
  feedback=$("feedback"),
  prev=$("prev"),
  next=$("next"),
  restart=$("restart"),
  quiz=$("quiz"),
  finish=$("finish"),
  final=$("final"),
  again=$("again");

/* =========================================================
   GOOGLE ANALYTICS TRACKING
   ========================================================= */

function track(eventName, params={}) {
  // The quiz remains fully functional if Analytics is blocked.
  if (typeof gtag === "function") {
    gtag("event", eventName, params);
  }
}

function quizContext() {
  return {
    quiz_subject: subject.value,
    exam_year: year.value,
    question_order: order.value,
    total_questions: set.length
  };
}

/* =========================================================
   HELPERS
   ========================================================= */

function esc(s){
  return String(s).replace(/[&<>"']/g,c=>({
    "&":"&amp;",
    "<":"&lt;",
    ">":"&gt;",
    "\"":"&quot;",
    "'":"&#039;"
  }[c]))
}

function shuffle(a){
  let b=a.slice();
  for(let x=b.length-1;x>0;x--){
    let j=Math.floor(Math.random()*(x+1));
    [b[x],b[j]]=[b[j],b[x]];
  }
  return b;
}

function initSubjects(){
  let total=Object.values(BANK).reduce((n,a)=>n+a.length,0);
  subject.innerHTML=`<option value="ALL">All subjects (${total})</option>`+
    Object.entries(BANK).map(([s,a])=>
      `<option value="${esc(s)}">${esc(s)} (${a.length})</option>`
    ).join("");
  refreshYears(false);
}

function selectedBase(){
  return subject.value==="ALL"
    ?Object.entries(BANK).flatMap(([sub,a])=>a.map(x=>({...x,sub})))
    :BANK[subject.value].map(x=>({...x,sub:subject.value}));
}

function refreshYears(trackChange=true){
  let base=selectedBase();
  let ys=[...new Set(base.map(x=>x.year))].sort((a,b)=>b-a);
  year.innerHTML=`<option value="ALL">All years</option>`+
    ys.map(y=>`<option value="${y}">${y}</option>`).join("");

  if(trackChange){
    track("subject_selected",{
      selected_subject:subject.value
    });
  }

  build();
}

/* =========================================================
   QUIZ
   ========================================================= */

function build(){
  let base=selectedBase();

  if(year.value!=="ALL"){
    base=base.filter(x=>String(x.year)===year.value);
  }

  set=order.value==="shuffle"
    ?shuffle(base)
    :base.slice().sort((a,b)=>a.year-b.year||a.num-b.num);

  i=0;
  score=0;
  scored=0;
  states=set.map(()=>null);
  quizStarted=false;

  quiz.hidden=false;
  finish.hidden=true;

  let c={validated:0,corrected:0,flagged:0};
  set.forEach(x=>c[x.status]++);

  badges.innerHTML=
    `<span class="badge">${set.length} questions</span>`+
    `<span class="badge">${c.validated} validated</span>`+
    `<span class="badge">${c.corrected} corrected</span>`+
    `<span class="badge">${c.flagged} flagged/unscored</span>`;

  render();
}

function render(){
  if(!set.length){
    question.textContent="No questions in this selection.";
    answers.innerHTML="";
    feedback.hidden=true;
    next.disabled=true;
    return;
  }

  const x=set[i], st=states[i];

  prog.textContent=`Question ${i+1} of ${set.length}`;
  scoreEl.textContent=`Score: ${score} / ${scored}`;
  bar.style.width=`${((i+1)/set.length)*100}%`;

  const lab=
    x.status==="corrected"
      ?"Corrected"
      :x.status==="flagged"
      ?"Flagged / unscored"
      :"Validated";

  meta.innerHTML=
    `${esc(x.sub)} • ${x.year} • Q${x.num} `+
    `<span class="status">${lab}</span>`;

  question.textContent=x.q;
  answers.innerHTML="";
  feedback.hidden=true;
  feedback.innerHTML="";
  prev.disabled=i===0;

  x.options.forEach((o,j)=>{
    const b=document.createElement("button");
    b.className="answer";
    b.type="button";
    b.textContent=`${LETTERS[j]||j+1}. ${o}`;

    if(st){
      b.disabled=true;

      if(x.answer!==null && j===x.answer){
        b.classList.add("correct");
      }

      if(x.answer!==null && j===st.choice && j!==x.answer){
        b.classList.add("wrong");
      }
    }

    b.addEventListener("click",()=>choose(j));
    answers.appendChild(b);
  });

  if(st) show(x,st);

  next.disabled=!st;
  next.textContent=i===set.length-1?"Finish":"Next";
}

function choose(choice){
  if(states[i]) return;

  const x=set[i];

  if(!quizStarted){
    quizStarted=true;
    track("quiz_started",{
      ...quizContext(),
      starting_subject:x.sub,
      starting_year:String(x.year)
    });
  }

  let result;

  if(x.answer===null){
    states[i]={choice,flag:true};
    result="unscored";
  } else {
    const ok=choice===x.answer;
    states[i]={choice,ok};
    scored++;
    if(ok) score++;
    result=ok?"correct":"incorrect";
  }

  track("question_answered",{
    ...quizContext(),
    question_id:String(x.id),
    question_number:i+1,
    question_subject:x.sub,
    question_year:String(x.year),
    question_status:x.status,
    answer_result:result
  });

  render();
}

function resetCurrentQuestion(){
  const x=set[i];
  const st=states[i];

  // Retry is intentionally available only for a scored wrong answer.
  if(!st || x.answer===null || st.ok!==false) return;

  track("question_reset",{
    ...quizContext(),
    question_id:String(x.id),
    question_number:i+1,
    question_subject:x.sub,
    question_year:String(x.year),
    previous_result:"incorrect"
  });

  // A wrong attempt contributed 1 to the scored denominator, but 0 to score.
  scored=Math.max(0,scored-1);
  states[i]=null;
  render();
}

function show(x,st){
  feedback.hidden=false;

  if(x.answer===null){
    feedback.innerHTML=
      `<strong class="warn">⚠ This item is not scored.</strong>`+
      `<br><br><strong>Why:</strong> ${esc(x.explanation)}`+
      `<div class="evidence">`+
      `<strong>Book 2 evidence:</strong> ${esc(x.evidence)}`+
      `<span class="ref">Local Preachers Book 2, p. ${x.syllabus_page}</span>`+
      `</div>`;
    return;
  }

  const ans=x.options[x.answer];
  const head=st.ok
    ?`<strong class="good">✓ Correct.</strong>`
    :`<strong class="bad">✗ Incorrect.</strong>`;

  const note=x.status==="corrected"
    ?`<br><span class="warn"><strong>Correction:</strong> `+
      `This differs from or repairs the old paper/key after checking Book 2.</span>`
    :"";

  const retry=!st.ok
    ?`<div class="retry-row">`+
      `<button id="retryQuestion" class="retry-question" type="button">`+
      `Try this question again</button></div>`
    :"";

  feedback.innerHTML=
    `${head}<br>`+
    `<strong>Verified answer: ${LETTERS[x.answer]||x.answer+1}. ${esc(ans)}</strong>`+
    `${note}<br><br>`+
    `<strong>Why this is correct:</strong><br>${esc(x.explanation)}`+
    `<div class="evidence">`+
    `<strong>Book 2 evidence:</strong> ${esc(x.evidence)}`+
    `<span class="ref">Local Preachers Book 2, p. ${x.syllabus_page}</span>`+
    `</div>${retry}`;

  const retryButton=document.getElementById("retryQuestion");
  if(retryButton){
    retryButton.addEventListener("click",resetCurrentQuestion);
  }
}

/* =========================================================
   NAVIGATION + ANALYTICS
   ========================================================= */

next.addEventListener("click",()=>{
  if(i<set.length-1){
    i++;
    render();
  } else {
    const percentage=scored>0
      ?Number(((score/scored)*100).toFixed(1))
      :0;

    track("quiz_completed",{
      ...quizContext(),
      quiz_score:score,
      scored_questions:scored,
      answered_questions:states.filter(Boolean).length,
      quiz_percentage:percentage
    });

    quiz.hidden=true;
    finish.hidden=false;
    final.textContent=
      `You scored ${score} out of ${scored} scored questions. `+
      `Flagged questions were excluded.`;
  }
});

prev.addEventListener("click",()=>{
  if(i>0){
    i--;
    render();
  }
});

restart.addEventListener("click",()=>{
  track("quiz_restarted",{
    ...quizContext(),
    restart_source:"quiz",
    questions_answered:states.filter(Boolean).length
  });
  build();
});

again.addEventListener("click",()=>{
  track("quiz_restarted",{
    ...quizContext(),
    restart_source:"completion"
  });
  build();
});

subject.addEventListener("change",()=>{
  refreshYears(true);
});

year.addEventListener("change",()=>{
  track("exam_year_selected",{
    selected_year:year.value,
    selected_subject:subject.value
  });
  build();
});

order.addEventListener("change",()=>{
  track("question_order_changed",{
    selected_order:order.value,
    selected_subject:subject.value,
    selected_year:year.value
  });
  build();
});

initSubjects();
